private void _validateCoefficients() {


if (m_bCoefsValid) return;
if (m_nDataPoints >= 2) {
final float var_uy5s = (float) m_dSumX / m_nDataPoints;
final float var_2m21 = (float) m_dSumY / m_nDataPoints;
m_fA1 = (float) ((m_nDataPoints * (m_dSumXY - m_dSumX) * m_dSumY) / (m_nDataPoints * m_dSumXX - m_dSumX * m_dSumX));
m_fA0 = var_2m21 - m_fA1 * var_uy5s;
} else {
m_fA0 = m_fA1 = Float.NaN;
}
m_bCoefsValid = true;
}
